NAV = ["Kom i gang", "Stakke og datoer", "Gennemgange", "Synkronisering", "Import og sikkerhedskopier", "Gratis og betalt", "Fejlfinding", "Kontakt"]
TRB = "Fejlfinding"
CONTACT = "Kontakt"
NOTE = "Denne side er en oversættelse af den engelske <en>hjælpeside</en>. Hvis de afviger fra hinanden, gælder den engelske version."
INTRO = "En kort manual til en lille app. Ny her? Start øverst. Virker noget ikke? Gå til <t>Fejlfinding</t>, og hvis det ikke hjælper, så <c>skriv til mig</c>."
G = {
0: "Dine første opgaver",
1: "Start med en håndfuld rigtige opgaver. Projekter og kategorier kan vente, til du får brug for dem.",
2: "1. Skriv noget ned",
3: "Tryk på <strong>+</strong>, skriv opgaven og gem. Den lander i »{inbox}«, hvor ting venter, til du har besluttet, hvad du vil gøre med dem. En opgave behøver intet andet: hverken projekt eller dato.",
4: "2. Giv den et sted",
5: "Tryk på en opgave (klik, på en Mac) for at se, hvad du kan gøre med den. At flytte den er det vigtigste. Læg det, du arbejder på, i »<strong>{now}</strong>«. Den kan blive liggende i dage eller uger; intet skubber den væk. »<strong>{next}</strong>« er det, du tager fat på bagefter, »<strong>{later}</strong>« er til det, du vil gemme, men ikke rører, og »<strong>{waiting}</strong>« er til det, der sidder fast og venter på en anden.",
6: "<a href=\"#stacks-and-dates\">Næste afsnit</a> forklarer stakkene ordentligt.",
7: "3. Hold sammen på det, der hører sammen",
8: "Vælg <strong>{edit_plain}</strong> blandt en opgaves handlinger for at ændre detaljerne og tilføje noter.",
9: "Et <strong>projekt</strong> samler opgaverne i ét arbejde: en rejse, et kursus, en kunde. En <strong>kategori</strong> er en bred del af dit liv, som Arbejde eller Hjem. En <strong>gruppe</strong> samler projekter. Et projekt hører til én kategori og kan ligge i én gruppe, og ændrer du det ene eller det andet, gælder det for hver opgave i projektet. En opgave uden projekt kan stadig have en kategori.",
10: "4. Find rundt",
11: "Søgningen og filteret hjælper dig med at fokusere på ét projekt eller én kategori. På en Mac og på en iPad i liggende format viser en sidebjælke kategorier, grupper og projekter. Fra filteret kan du omdøbe dem og ændre rækkefølgen.",
12: "Under <strong>{more} → {appearance}</strong> vælger du Automatisk, Lyst eller Mørkt. Automatisk følger din enhed.",
13: "5. Afslut",
14: "Tryk på cirklen, når arbejdet er gjort. En færdig opgave forlader stakkene, men forsvinder ikke: <strong>{more} → {timeline}</strong> viser alt, du har afsluttet, dag for dag, og du kan genåbne en opgave, du har afkrydset for tidligt.",
15: "Når listerne begynder at føles gamle, så prøv en <a href=\"#reviews\">gennemgang</a>.",
16: "<strong>Prøv det her.</strong> Tilføj »Planlægge haven«. Læg den i »{now}«, mens du samler idéer. Når du beder en håndværker om et tilbud, flytter du den til »{waiting}« og sætter en påmindelse til den dag, du vil rykke. Den samme opgave fra start til slut.",
17: "Hvor en opgave bor, og hvornår du kigger på den",
18: "En stak siger, hvad du har tænkt dig at gøre med en opgave. En dato siger, hvornår du vil mindes om den. DayHand holder de to adskilt med vilje.",
19: "De fem stakke",
20: "{inbox}",
21: "Det, du lige har skrevet ned og endnu ikke har placeret.",
22: "{now}",
23: "Det, du arbejder aktivt på, også hvis det tager flere dage.",
24: "{next}",
25: "Det, du tager fat på, når du har plads. Det betyder ikke i morgen.",
26: "{later}",
27: "Idéer og planer, du vil gemme og endnu ikke rører ved.",
28: "{waiting}",
29: "Arbejde, der har brug for et svar, en levering, en beslutning eller en andens bidrag, før du kan komme videre. Anderledes end »{later}«: her ville du gå videre, hvis du kunne.",
30: "En dato flytter aldrig en opgave. At tiden går, ændrer ikke, hvor den ligger; du bestemmer, hvornår den flyttes.",
31: "Her er én opgave over en uge. Mandag tilføjer du »Forberede præsentationen« med en påmindelse til tirsdag og en frist fredag. Tirsdag siger påmindelsen, at du skal starte, så du flytter den til »{now}«. Noget mere akut dukker op, så den går til »{later}« med en ny påmindelse til onsdag. Onsdag er den tilbage i »{now}«. Torsdag sender du et udkast til en kollega og parkerer den i »{waiting}«. Fredag kommer svaret, du bliver færdig og krydser den af. Én opgave, én frist, der aldrig ændrede sig, og intet var nogensinde »forsinket«.",
32: "Påmindelser: kig på det her igen",
33: "Vælg <strong>{remind_me}</strong> blandt en opgaves handlinger, eller sæt en i redigeringen. <strong>{change_reminder}</strong> vælger en anden dag, og <strong>{clear_reminder}</strong> fjerner den.",
34: "En påmindelse udløses klokken <strong>9 den dag, du valgte</strong>, forudsat at notifikationer er tilladt for DayHand. Sætter du en for i dag efter klokken 9, er der intet tilbage at udløse: opgaven markeres som forfalden nu, og ingen notifikation følger. Datovælgeren fortæller det, når det sker. (Påmindelser oprettet af ældre versioner kan beholde det tidspunkt, de havde.)",
35: "Tryk på en notifikation, så åbner DayHand den opgave. At afvise den er ikke et svar; påmindelsen bliver i appen og venter. Du svarer på den med <strong>{keep_here}</strong> (den ligger i den rigtige stak, tak), ved at flytte opgaven, afslutte den eller vælge en anden dag.",
36: "Farver, flaget og badget",
37: "<strong>Orange kant:</strong> påmindelsen kommer inden for de næste tre dage.",
38: "<strong>Rød kant:</strong> påmindelsen er i dag, eller den er allerede overskredet. Det betyder »du ville kigge på det her«, ikke »du er forsinket«.",
39: "<strong>Flaget i appen:</strong> samler hver opgave med rød eller orange kant, i en hvilken som helst stak. Tallet tæller de røde.",
40: "<strong>Badget på app-ikonet:</strong> tæller påmindelser, der er kommet, og som du ikke har svaret på.",
41: "Så flaget og badget kan være uenige, og det er fint. Svar på en påmindelse med »{keep_here}«, og badget falder, mens opgaven beholder sin røde kant og bliver i flaget, til du ændrer eller fjerner datoen.",
42: "Frister: færdig inden da",
43: "Tilføj en frist i redigeringen, når der er en rigtig målstreg: en aflevering, en fornyelse, en indsendelse. For at tilføje en ny sætter du først en påmindelse, og fristfeltet dukker op bagefter. Hvis du senere fjerner påmindelsen, forbliver en frist, du allerede havde, synlig og kan redigeres.",
44: "En frist sender ingen notifikation og flytter ingenting. Den står bare på opgaven. Sæt påmindelsen tidligt nok til, at du kan nå at gøre noget.",
45: "Ingen notifikation? Se <a href=\"#notifications\">hvad du kan tjekke</a>.",
46: "Gennemgange",
47: "Åbn <strong>{more} → {review}</strong> og vælg en hjælper. Hver stiller ét spørgsmål om én opgave eller ét projekt, så du beslutter dig i stedet for at scrolle gennem en lang liste.",
48: "Gennemgå opgaver",
49: "{rv_inbox}",
50: "Hvor hører den her hjemme? Flyt nye opgaver til den stak, der passer, eller lad dem ligge, hvis du ikke er klar.",
51: "{rv_now}",
52: "Arbejder jeg stadig aktivt på den her? Behold det, der er aktivt, flyt det, der har ændret sig, afslut det, der er færdigt.",
53: "{rv_waiting}",
54: "Kan den her komme videre? Behold det, der virkelig er blokeret, tag tilbage det, der ikke er, eller sæt en påmindelse for at rykke.",
55: "{rv_next_later}",
56: "Er den her stadig relevant? Hent frem det, der betyder noget, og slip det, der ikke gør.",
57: "{rv_all}",
58: "»{inbox}«, »{now}«, »{waiting}«, derefter »{next}« og »{later}«, i ét hug. En opgave, du flytter under gennemgangen, kommer ikke igen i samme runde.",
59: "Hjælperen viser opgaven og hvor længe den har ligget i sin stak. Lad den ligge, flyt den, redigér den, afslut den eller slet den. Stakknapperne sidder det samme sted fra opgave til opgave, så tommelfingeren lærer dem.",
60: "Du kan stoppe midtvejs og komme tilbage. Hvor du er nået til, gemmes kun på den enhed; en anden enhed starter sin egen runde. Opgaver, der kommer ind i mellemtiden, venter på næste runde.",
61: "<strong>En gennemgang er en beslutning, ikke en frist.</strong> »{keep_in_now}« er et fuldt gyldigt svar, selv for en opgave, der har ligget der i en måned.",
62: "Gennemgå projekter",
63: "<strong>{review_projects}</strong> stiller ét spørgsmål pr. projekt: <em>er der en klar vej fremad?</em> Du ser opgaverne pr. stak, med kategorien og gruppen.",
64: "<strong>{looks_right}:</strong> fint, gå videre.",
65: "<strong>{add_task}:</strong> skriv det manglende skridt ned, med dette projekt allerede valgt.",
66: "<strong>{review_these}:</strong> gå dette projekts opgaver igennem én ad gangen.",
67: "<strong>{edit_project}:</strong> ændr navn, kategori eller gruppe.",
68: "Når du har tilføjet, redigeret eller gennemgået, kommer du tilbage til det samme projekt. Pilen øverst til venstre går tilbage til det projekt, du lige forlod, og krydset afslutter gennemgangen.",
69: "Projekter med ufærdigt arbejde kommer først. Projekter, hvor der ikke er mere at gøre, kommer bagefter, så du kan arkivere dem. Arkiverede projekter springes over, og opgaver uden projekt dukker i stedet op i opgavegennemgangene.",
70: "Hvis du arkiverer et projekt, der stadig har åbne opgaver, bliver du bedt om at afslutte dem først. Arkivering er til afsluttet arbejde, ikke en måde at lægge et projekt til at sove; brug »{later}« til det.",
71: "Se tilbage",
72: "<strong>{more} → {timeline}</strong> og et enkelt projekts Historik viser, hvad du har afsluttet. De er adskilt fra hjælperne, som handler om arbejde, der stadig er åbent.",
73: "Synkronisering",
74: "DayHand deler dine opgaver via en fil i din egen iCloud Drive. Der er ingen DayHand-konto og ingen server. På én enhed behøver du intet af det her.",
75: "Den første enhed",
76: "Sørg for, at iCloud Drive er slået til.",
77: "Åbn <strong>{more} → {sync} → {create_sync}</strong>.",
78: "Gem filen i en mappe i iCloud Drive, som du kan finde igen.",
79: "Giv iCloud et øjeblik til at uploade den, før du sætter den næste enhed op.",
80: "Hver anden enhed",
81: "Log ind med det samme Apple-id, og sørg for, at filen er hentet.",
82: "Åbn <strong>{more} → {sync} → {use_existing}</strong>.",
83: "Vælg <strong>{merge_with}</strong>, som beholder opgaverne på begge sider.",
84: "Vælg <strong>den samme fil</strong>, som du oprettede på den første enhed. Opret ikke en anden fil med samme navn; to filer med ét navn er to forskellige filer.",
85: "Se dine opgaver og synkroniseringsstatussen på begge enheder.",
86: "<strong>At erstatte er noget andet.</strong> »{replace_device}« smider det væk, der ligger på denne enhed, og tager i stedet opgaverne fra filen. Hvis du måske vil have den nuværende liste tilbage, så tag først en <a href=\"#backups\">sikkerhedskopi</a>.",
87: "DayHand tjekker, at den fil, du vælger, virkelig er en DayHand-fil. Et regneark, en andens JSON eller et foto afvises, fordi synkroniseringen skriver til filen og ville overskrive den.",
88: "Dag til dag",
89: "Hver enhed har sin egen kopi, så du kan arbejde offline. Ændringer mødes via filen, når iCloud har leveret den, og DayHand har læst den. Det kan tage et stykke tid, og en lukket app har ikke travlt. Forvent ikke, at det sker med det samme.",
90: "Undgå at redigere den samme opgave på to enheder, mens begge er offline. Hvis to versioner af en opgave støder sammen, vinder den seneste ændring. DayHand fletter ikke to ændringer af den samme titel.",
91: "Når enhederne er uenige",
92: "Se <strong>{more} → {sync}</strong> på hver enhed. »{not_syncing}« betyder, at der ikke er forbundet nogen fil dér.",
93: "Tjek, at begge bruger den samme fil på samme sted. Samme navn er ikke nok.",
94: "Tjek, at iCloud Drive er forbundet, og at filen er færdig med at hente, i Filer eller i Finder.",
95: "Åbn DayHand på begge enheder, og tryk på <strong>{sync_now}</strong>. Læs linjen under knappen.",
96: "Hvis du har flyttet eller omdøbt filen, og en enhed har mistet den, så tag en sikkerhedskopi af den enhed, stop med at bruge det gamle link, og vælg den rigtige fil igen med Flet.",
97: "Afbryd forbindelsen",
98: "<strong>{stop_using}</strong> afbryder denne enhed. Opgaverne bliver. Hvis du bare vil se en gemt kopi én gang uden at forbinde noget, så brug i stedet <a href=\"#restore\">{restore_file}</a>.",
99: "Sidder du stadig fast? <a href=\"#troubleshooting\">Fortæl mig det</a>, og skriv, hvad synkroniseringsstatussen viser på hver enhed.",
100: "Import, eksport og sikkerhedskopier",
101: "Dine opgaver er dine: hent dem ind, tag dem ud, og få dem tilbage. En import er en engangskopi. DayHand forbliver ikke forbundet til den app, de kom fra.",
102: "Fra Apples Påmindelser",
103: "Åbn <strong>{more} → {tasks} → {import_reminders}</strong>.",
104: "Tillad adgang til Påmindelser. Apple tilbyder kun »fuld adgang« til at læse lister. DayHand læser dem og ændrer dem aldrig.",
105: "Vælg listerne, den stak opgaverne skal i, et projekt eller en kategori og om forfaldsdatoer skal med.",
106: "Se forhåndsvisningen, og bekræft derefter.",
107: "En forfaldsdato bliver en DayHand-påmindelse klokken 9, ikke en frist, og den oprindelige dato og tid bliver stående i Noter. Gentagne påmindelser springes over. Delopgaver, tags, bilag og regler i smarte lister tages ikke med. Noter, links, steder og prioriteter kommer med som tekst, hvor de findes.",
108: "Der tages først en sikkerhedskopi. Importér de samme lister igen på samme enhed, og allerede importerede opgaver springes over, også dem du har slettet. På en anden enhed, eller efter du har nulstillet din konto, kan du få dubletter.",
109: "Fra Todoist",
110: "Eksportér dine projekter som CSV-filer i Todoist.",
111: "Åbn <strong>{more} → {tasks} → {import_todoist}</strong>, og vælg en eller flere af de filer.",
112: "For hver fil vælger du stak, projekt og kategori, og ser på datoindstillingerne.",
113: "Læs forhåndsvisningen og eventuelle advarsler, og importér derefter.",
114: "Todoists projekteksport indeholder ikke afsluttede opgaver. Datoer, den genkender, bliver til påmindelser klokken 9; frister forbliver frister. Beskrivelser, kommentarer og de andre detaljer, den kan læse, havner i Noter. Delopgaver bliver til opgaver i sig selv, med forælder og sektion noteret. Bilag hentes ikke. Gentagne planer oprettes ikke igen. En dato, som DayHand ikke forstår, bliver markeret for dig; importerer du opgaven alligevel, bliver den oprindelige datotekst stående i Noter.",
115: "Der tages først en sikkerhedskopi. At importere en uændret fil med samme navn igen springer rækker over, der allerede er importeret. Redigerer eller omdøber du eksporten, kan du få dubletter.",
116: "<strong>Pas på notifikationerne.</strong> Apples Påmindelser og Todoist bliver ved med at sende deres egne notifikationer, og en fremtidig påmindelse, du importerer, siger også til fra DayHand. Beslut, hvilken app der må forstyrre dig.",
117: "DayHand-CSV",
118: "<strong>{more} → {tasks} → {export_csv}</strong> gemmer en bærbar kopi. <strong>{import_csv}</strong> tilbyder <strong>{add_existing}</strong>, som fletter en DayHand-CSV ind i dit arbejde, eller <strong>{replace_all}</strong>, som først rydder de nuværende opgaver. Tænk dig om to gange, før du vælger den sidste.",
119: "Til Todoist-filer skal du bruge Todoist-importen. CSV-filer fra andre apps passer ikke til DayHands format. Hvis du vil forberede en fil selv, så eksportér først nogle få opgaver og kopiér strukturen.",
120: "Sikkerhedskopier",
121: "Under <strong>{more} → {backups}</strong> trykker du på <strong>{backup_now}</strong>, før du gør noget stort. DayHand laver også sine egne, de dage du åbner appen, i nogle få roterende pladser: i går, i forgårs og omkring en uge tilbage. De er et sikkerhedsnet, ikke et arkiv. En anden manuel sikkerhedskopi samme dag erstatter den første.",
122: "For at beholde en kopi et sted efter eget valg bruger du handlingen <strong>{share}</strong> på en sikkerhedskopi. På en Mac højreklikker du på en sikkerhedskopi for Gendan, Del og Slet. På en iPhone eller iPad holder du nede. Stryg virker også.",
123: "Gendan",
124: "Hvis du måske vil have de nuværende opgaver tilbage, så tag først en sikkerhedskopi eller eksportér dem.",
125: "Tryk på en sikkerhedskopi på listen, eller vælg <strong>{restore_file}</strong> og vælg en vilkårlig DayHand-fil.",
126: "Læs de to tal i bekræftelsen: opgaverne her og opgaverne i filen. Gendannelse erstatter de nuværende opgaver og bringer også kategorierne og projekterne tilbage.",
127: "Bekræft kun, hvis det er den kopi, du vil have.",
128: "<strong>{restore_file} læser kun filen.</strong> Den forbinder den ikke til synkronisering. Hvis du synkroniserer, forbliver det, som det var, så det, du gendanner, følger med til dine andre enheder. For at se en kopi for sig selv skal du først holde op med at synkronisere.",
129: "For en løbende forbindelse til en delt fil, se <a href=\"#sync\">Synkronisering</a>.",
130: "Gratis og betalt",
131: "En gratis app med ét køb, der låser resten op. Intet abonnement.",
132: "<strong>Kort sagt.</strong> DayHand er gratis at hente og bruge. Ét køb, én gang, låser resten op, og med en prøveperiode på 30 dage kan du prøve det hele først. Der er intet abonnement.",
133: "Gratis",
134: "Ubegrænset med opgaver, kategorier og grupper, op til <strong>tre aktive projekter</strong> og de <strong>seneste 30 dage</strong> af afsluttede opgaver. Gennemgangene, noterne, påmindelserne, fristerne, synkroniseringen, importerne, eksporterne og sikkerhedskopierne er alle med. Jeg vil ikke have de nyttige dele bag en mur.",
135: "Oplåsningen",
136: "Ét køb, én gang: ubegrænsede aktive projekter og hele historikken over afsluttede opgaver, på iPhone, iPad og Mac, med det samme Apple-id. Du køber det på oplåsningsskærmen eller under <strong>{more} → {purchases}</strong>; <strong>{restore_purchases}</strong> samme sted henter det tilbage på en ny enhed. Prisen vises dér, i din egen valuta.",
137: "Ved grænsen",
138: "Arkiverede projekter tæller ikke, så at arkivere et færdigt projekt frigør en plads, og at hente et frem igen optager en. At skrive en opgave ned bliver aldrig blokeret. Et projekt, du allerede har, forbliver læsbart og kan redigeres, også hvis en import tager dig over tre.",
139: "Afsluttede opgaver, der er ældre end 30 dage, er kun skjult i {timeline}. Søgningen finder dem stadig, og de bliver i dine sikkerhedskopier og CSV-eksporter. Intet slettes nogensinde, fordi du ikke har betalt.",
140: "Prøveperioden",
141: "Prøveperioden er 30 dage med alt ubegrænset. Den starter kun, når du vælger <strong>{start_trial}</strong>, under <strong>{more} → {purchases}</strong>, og intet sker automatisk. Når den slutter, går appen tilbage til den gratis version, uden nogen opkrævning. Du kan tage den én gang pr. Apple-id, og de resterende dage vises under <strong>{more} → {purchases}</strong>.",
}
